#!/usr/bin/env python3

import rclpy
from rclpy.node import Node
from bodyctrl_msgs.msg import MotorStatusMsg, MotorStatus, CmdMotorCtrl, CmdSetMotorPosition
from std_msgs.msg import Header
import math
import time

angle_dict = {
    11: 0.0,
    12: 0.0,
    13: 0.0,
    14: 0.0,
    15: 0.0,
    16: 0.0,
    17: 0.0,
    21: 0.0,
    22: 0.0,
    23: 0.0,
    24: 0.0,
    25: 0.0,
    26: 0.0,
    27: 0.0,
}

# 腿部电机位置命令 (51, 52)
leg_cmd_pos = {51: 0.0, 52: 0.0}
# 腰部电机位置命令 (31, 32)
waist_cmd_pos = {31: 0.0, 32: 0.0}

class TianyiMotorSimulator(Node):
    """天轶电机状态模拟器节点"""
    
    def __init__(self):
        super().__init__('tianyi_motor_simulator')

        # 定义回调函数
        def arm_cmd_callback(msg):
            for cmd in msg.cmds:
                angle_dict[cmd.name] = cmd.pos
                print(cmd.name, cmd.pos)
                
            
        # 订阅CmdMotorCtrl类型消息，/arm/cmd_ctrl
        self.arm_cmd_sub = self.create_subscription(
            CmdMotorCtrl,
            '/arm/cmd_ctrl',
            arm_cmd_callback,
            10
        )

        # 定义腿部命令回调函数
        def leg_cmd_callback(msg):
            global leg_cmd_pos
            for cmd in msg.cmds:
                leg_cmd_pos[cmd.name] = cmd.pos

        # 定义腰部命令回调函数
        def waist_cmd_callback(msg):
            global waist_cmd_pos
            for cmd in msg.cmds:
                waist_cmd_pos[cmd.name] = cmd.pos

        # 订阅 /leg/cmd_pos 话题
        self.leg_cmd_sub = self.create_subscription(
            CmdSetMotorPosition,
            '/leg/cmd_pos',
            leg_cmd_callback,
            10
        )

        # 订阅 /waist/cmd_pos 话题
        self.waist_cmd_sub = self.create_subscription(
            CmdSetMotorPosition,
            '/waist/cmd_pos',
            waist_cmd_callback,
            10
        )


        # 创建发布者
        self.arm_status_pub = self.create_publisher(
            MotorStatusMsg, 
            '/arm/status', 
            10
        )
        
        self.waist_status_pub = self.create_publisher(
            MotorStatusMsg, 
            '/waist/status', 
            10
        )
        
        self.leg_status_pub = self.create_publisher(
            MotorStatusMsg, 
            '/leg/status', 
            10
        )
        
        self.head_status_pub = self.create_publisher(
            MotorStatusMsg, 
            '/head/status', 
            10
        )
        
        # 创建定时器，100Hz发布频率
        self.timer = self.create_timer(0.01, self.publish_motor_status)
        
        # 初始化电机数据
        # 左臂电机 (11-17)
        self.arm_left_motors = [11, 12, 13, 14, 15, 16, 17]
        # 右臂电机 (21-27)  
        self.arm_right_motors = [21, 22, 23, 24, 25, 26, 27]
        # 腰部电机 (31-32)
        self.waist_motors = [31, 32]
        # 腿部电机 (51-52)
        self.leg_motors = [51, 52]
        # 头部电机 (1-3)
        self.head_motors = [1, 2, 3]
        
        # 所有电机
        self.all_motors = (self.arm_left_motors + self.arm_right_motors + 
                          self.waist_motors + self.leg_motors + self.head_motors)
        
        # 电机状态数据
        self.motor_states = {}
        for motor_id in self.all_motors:
            self.motor_states[motor_id] = {
                'position': 0.0,
                'velocity': 0.0,
                'current': 0.0,
                'temperature': 25.0,
                'error': 0
            }
        
        self.get_logger().info('天轶电机状态模拟器已启动')
        self.get_logger().info('订阅话题: /arm/cmd_ctrl, /leg/cmd_pos, /waist/cmd_pos')
        self.get_logger().info('发布话题: /arm/status, /waist/status, /leg/status, /head/status')
        self.get_logger().info(f'总电机数量: {len(self.all_motors)}')
        self.get_logger().info(f'  - 左臂电机: {len(self.arm_left_motors)}个')
        self.get_logger().info(f'  - 右臂电机: {len(self.arm_right_motors)}个')
        self.get_logger().info(f'  - 腰部电机: {len(self.waist_motors)}个')
        self.get_logger().info(f'  - 腿电机: {len(self.leg_motors)}个')
        self.get_logger().info(f'  - 头部电机: {len(self.head_motors)}个')    
    def publish_motor_status(self):
        """发布电机状态消息"""
        current_time = time.time()
        
        # 发布手臂电机状态
        self.publish_motor_group_status(
            self.arm_left_motors + self.arm_right_motors,
            self.arm_status_pub,
            current_time,
            "手臂"
        )
        
        # 发布腰部电机状态
        self.publish_motor_group_status(
            self.waist_motors,
            self.waist_status_pub,
            current_time,
            "腰部"
        )
        
        # 发布腿部电机状态
        self.publish_motor_group_status(
            self.leg_motors,
            self.leg_status_pub,
            current_time,
            "腿部"
        )
        
        # 发布头部电机状态
        self.publish_motor_group_status(
            self.head_motors,
            self.head_status_pub,
            current_time,
            "头部"
        )
        
        # 每5秒打印一次状态信息
        # if int(current_time) % 5 == 0:
        #     self.get_logger().info(f'发布电机状态 - 时间: {current_time:.1f}s')
    
    def publish_motor_group_status(self, motor_list, publisher, current_time, group_name):
        """发布指定电机组的状态"""
        msg = MotorStatusMsg()
        
        # 设置消息头
        msg.header = Header()
        msg.header.stamp = self.get_clock().now().to_msg()
        msg.header.frame_id = 'base_link'
        
        # 生成电机状态数据
        msg.status = []
        
        for i, motor_id in enumerate(motor_list):
            motor_status = MotorStatus()
            motor_status.name = motor_id
            
            # 根据电机组设置不同的运动模式
            if group_name == "手臂":
                # 手臂：较快的运动
                motor_status.pos = angle_dict[motor_id]
                motor_status.speed = 0.0
                motor_status.current = 0.1 + 0.02 * math.sin(current_time * 3.0 + i * 0.3)
                motor_status.temperature = 28.0 + 3.0 * math.sin(current_time * 0.2 + i * 0.15)
                
            elif group_name == "腰部":
                # 腰部：使用订阅到的位置命令
                motor_status.pos = waist_cmd_pos.get(motor_id, 0.0)
                motor_status.speed = 0.0
                motor_status.current = 0.2 + 0.05 * math.sin(current_time * 1.0)
                motor_status.temperature = 30.0 + 2.0 * math.sin(current_time * 0.1)

            elif group_name == "腿部":
                # 腿部：使用订阅到的位置命令
                motor_status.pos = leg_cmd_pos.get(motor_id, 0.0)
                motor_status.speed = 0.0
                motor_status.current = 0.3 + 0.1 * math.sin(current_time * 2.0 + i * 0.4)
                motor_status.temperature = 32.0 + 4.0 * math.sin(current_time * 0.15 + i * 0.2)
                
            elif group_name == "头部":
                # 头部：缓慢转动和点头
                motor_status.pos = 0.0
                motor_status.speed = 0.2 * 0.4 * math.cos(current_time * 0.4 + i * 0.8)
                motor_status.current = 0.05 + 0.02 * math.sin(current_time * 1.5 + i * 0.5)
                motor_status.temperature = 26.0 + 2.0 * math.sin(current_time * 0.3 + i * 0.1)
            
            # 错误状态：通常为0（无错误）
            motor_status.error = 0
            
            msg.status.append(motor_status)
        
        # 发布消息
        publisher.publish(msg)


def main(args=None):
    """主函数"""
    rclpy.init(args=args)
    
    try:
        # 创建节点
        node = TianyiMotorSimulator()
        
        # 运行节点
        rclpy.spin(node)
        
    except KeyboardInterrupt:
        print('\n收到中断信号，正在关闭节点...')
    except Exception as e:
        print(f'节点运行出错: {e}')
    finally:
        # 清理资源
        if rclpy.ok():
            rclpy.shutdown()


if __name__ == '__main__':
    main()
